  const T={},nowS=S.polled_at;
  const team=n=>T[n]||(T[n]={team:n,runs:0,secs:0,calls:0,cost:0,deep:0,last:0,starts:0,starts30:0,dc:0,ds:0});
  for(const r of S.all){
    if(!/test/i.test(r.kind||''))continue;
    const t=team(r.team);
    t.starts++;if(nowS-r.first<1800)t.starts30++;t.last=Math.max(t.last,r.last);
    if(!(r.secs>=20)||!(r.calls>0))continue;
    t.runs++;t.secs+=r.secs;t.calls+=r.calls;t.cost+=r.cost;t.deep=Math.max(t.deep,r.secs);
    // recent slope (last ~2 min of the run) for the "at current pace" projection
    const sm=r.samples,e=sm[sm.length-1];let p=sm[0];for(const q of sm){if(e[1]-q[1]>=120){p=q}else break}
