    TL.map((t,i)=>`<tr class="${t.team===US?'us':''}"><td>${i+1}</td><td class="l">${esc(t.team)}</td><td>${t.starts30}</td><td>${t.starts}</td>
    <td>${t.runs?(t.calls/t.secs*60).toFixed(0):'–'}</td><td>${t.runs?usd(t.cost/t.secs*60):'–'}</td><td>${t.runs?usd(t.cost/t.calls):'–'}</td>
    <td>${t.ds>0?usd(t.dc/t.ds*1200):'–'}</td><td>${t.runs?fmtT(t.deep):'–'}</td><td class="mute">${ago(t.last*1000)}</td></tr>`).join('')+'</tbody>'
    :'<tbody><tr><td class="empty">No test runs recorded yet.</td></tr></tbody>';

  // scored submissions currently being reviewed / evaluated
  const ev2=(L.leaderboard&&L.leaderboard.evaluating)||[];
  $('evalNow').innerHTML=ev2.length?'In evaluation now: '+ev2.map(e=>`<b>${esc(e.team_name)}</b> (submission ${e.submission_count}, review ${esc(e.review_status||'pending')})`).join(', '):'Nothing in evaluation right now.';

  // how each team's scored submissions evolved
  const trail=(h,i,f)=>h.slice(-6).map(x=>x[i]==null?'–':f(x[i])).join(' → ');
  const IT=E.filter(e=>(e.hist||[]).length).sort((a,b)=>(b.hist[b.hist.length-1][0]||0)-(a.hist[a.hist.length-1][0]||0));
  $('iter').innerHTML=IT.length?`<thead><tr><th class="l">Team</th><th>Subs</th><th class="l">Quality (oldest → newest)</th><th class="l">Cost</th><th class="l">Time</th><th>Last submitted</th></tr></thead><tbody>`+
    IT.map(e=>{const h=e.hist;return `<tr class="${e.team_name===US?'us':''}"><td class="l">${esc(e.team_name)}</td><td>${e.submission_count}</td>
    <td class="l">${trail(h,1,v=>v)}</td><td class="l mute">${trail(h,2,v=>v?usd(v/1e6):'–')}</td><td class="l mute">${trail(h,3,v=>v?fmtT(v/1000):'–')}</td>
    <td class="mute">${ago(h[h.length-1][0])}</td></tr>`}).join('')+'</tbody>'
    :'<tbody><tr><td class="empty">No submissions yet.</td></tr></tbody>';

"""
s = s[:a] + block + s[b:]

# 4. markup: evaluating line in the activity card, trajectory section
s = s.replace('<div class="card"><ul class="feed" id="feed"></ul></div>',
              '<div class="card"><div id="evalNow" class="hint" style="padding:10px 12px;margin:0;border-bottom:1px solid var(--line)"></div><ul class="feed" id="feed"></ul></div>', 1)
s = s.replace("</main>", """<section>
  <h2>How teams iterate</h2>
  <p class="hint">Each team's scored submissions in order, from the public leaderboard history: quality, cost and time of each, so you can see who is still improving and who is trading quality for cost.</p>
